  u2_l10: () => { const b = BD('u2_l10'); const EM = ['🏞️', '📜', '🎭', '🌾']; return { k: 'groups', bins: b.AL_KINDS.map((k, i) => ({ name: k, emoji: EM[i], tone: 't' + i, items: b.AL_SHORT.map((s, j) => j).filter(j => b.AL_FIT[j] & (1 << i)).map(j => ({ emoji: '📣', name: b.AL_SHORT[j] })) })), note: '「' + b.AL_SHORT[0] + '」는 네 갈래 어디에나 설 수 있어요' }; },
  u2_l12: () => { const b = BD('u2_l12'); return { k: 'groups', bins: b.MK_WAY.map((w, i) => ({ name: w, emoji: ['💬', '🖼️', '🗺️'][i], tone: 't' + i, items: b.MK_STEP[i].map((s, j) => ({ emoji: NUM[j], name: s })), hint: '걸음 **' + b.MK_STEP[i].length + '**' })) }; },
  u2_l14: () => { const b = BD('u2_l14'); return { k: 'groups', bins: b.SP_PAPER.map((p, i) => ({ name: p, emoji: ['✍️', '🛍️'][i], tone: 't' + i, items: b.SP_SLOT[i].map((s, j) => ({ emoji: NUM[j], name: s })), hint: '이 장 **' + b.SP_SLOT[i].length + '칸**만 다 채워도 판이 닫혀요' })) }; },
